  gap: 6px;
  padding: 10px 0;
  margin-bottom: 8px;
}
.csfloat-quicktoggle {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 12px;
  background: var(--bg-1);
  border: 1px solid var(--line);
  border-radius: 999px;
  font-size: 11px;
  font-weight: 500;
  color: var(--ink-2);
  cursor: pointer;
  transition: background 120ms ease, color 120ms ease, border-color 120ms ease;
}
.csfloat-quicktoggle:hover {
  background: var(--bg-2);
  color: var(--ink-1);
  border-color: var(--line-2);
}
.csfloat-quicktoggle.active {
  background: oklch(0.30 0.05 250 / 0.18);
  border-color: var(--cta);
