  border-radius: 4px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: background 120ms ease, color 120ms ease;
}
.csfloat-view-toggle-btn:hover { color: var(--ink-1); }
.csfloat-view-toggle-btn.active {
  background: var(--bg);
  color: var(--ink-1);
}

/* CSFloat-1:1: per-page selector. */
.csfloat-perpage {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  color: var(--ink-3);
}
.csfloat-perpage select {
  background: var(--bg-1);
  border: 1px solid var(--line);
  border-radius: 4px;
  padding: 3px 6px;
  color: var(--ink-1);
  font-family: var(--mono);
  font-size: 11px;
  cursor: pointer;
  font-variant-numeric: tabular-nums;
}

/* END quicktoggles + sort + view + perpage */

/* CSFloat-1:1: list view layout — alternative to grid view, denser table-like rows. */
.csfloat-grid.list-view {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.csfloat-grid.list-view .csfloat-grid-card {
  display: grid;
  grid-template-columns: 56px 1fr auto auto;
  gap: 14px;
  padding: 10px 14px;
  align-items: center;
}
.csfloat-grid.list-view .csfloat-grid-card-img {
  width: 56px;
  height: 56px;
  aspect-ratio: 1;
  background: var(--bg-2);
  border: 1px solid var(--line);
  border-radius: 6px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 4px;
}
.csfloat-grid.list-view .csfloat-grid-card-img img {
  width: 100%;
  height: 100%;
  object-fit: contain;
}
.csfloat-grid.list-view .csfloat-grid-card-info {
  min-width: 0;
}
.csfloat-grid.list-view .csfloat-grid-card-name {
  font-size: 13px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.csfloat-grid.list-view .csfloat-grid-card-floatbar {
  width: 80px;
}
.csfloat-grid.list-view .csfloat-grid-card-pricerow {
  text-align: right;
}

/* CSFloat-1:1: empty grid placeholder — when filters return no results. */
.csfloat-grid-empty {
  grid-column: 1 / -1;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  padding: 80px 20px;
  gap: 12px;
}
.csfloat-grid-empty-icon {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  background: var(--bg-2);
  border: 1px solid var(--line);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--ink-4);
  font-size: 22px;
}
.csfloat-grid-empty-title {
  font-size: 18px;
  font-weight: 600;
  color: var(--ink-1);
  margin: 0;
}
.csfloat-grid-empty-desc {
  font-size: 13px;
  color: var(--ink-3);
