  background-clip: text;
  -webkit-text-fill-color: transparent;
  margin: 0;
}
.csfloat-404-title {
  font-size: 22px;
  font-weight: 600;
  color: var(--ink-1);
  margin: 0;
  letter-spacing: -0.015em;
}
.csfloat-404-desc {
  font-size: 14px;
  color: var(--ink-3);
  margin: 0;
  max-width: 420px;
  line-height: 1.6;
}
