}
.csfloat-chip-arrow:hover {
  background: var(--bg-3);
  color: var(--cta);
  border-color: var(--cta);
  padding-right: 14px;
}
.csfloat-chip-arrow::after {
  content: "→";
  font-size: 11px;
  color: var(--ink-3);
  transition: transform 200ms cubic-bezier(0.2, 0.8, 0.2, 1), color 120ms ease;
}
