  font-weight: 700;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.csfloat-inline-message-success {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 8px;
  background: oklch(0.30 0.04 152 / 0.18);
  border: 1px solid oklch(0.42 0.07 152 / 0.36);
  border-radius: 4px;
  font-size: 11px;
  font-weight: 500;
  color: oklch(0.84 0.18 152);
}
.csfloat-inline-message-success::before {
  content: "✓";
  width: 12px;
  height: 12px;
  background: oklch(0.78 0.18 152);
  color: oklch(0.10 0 0);
  border-radius: 50%;
  font-size: 9px;
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.csfloat-inline-message-info {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 8px;
  background: oklch(0.30 0.05 250 / 0.18);
  border: 1px solid oklch(0.42 0.10 250 / 0.36);
