  font-size: 10px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--ink-4);
  font-weight: 600;
}
.csfloat-book-spread-value {
  color: var(--ink-1);
  font-weight: 600;
}

/* CSFloat-1:1: market price tag block — for item title/header area */
.csfloat-price-tag {
  display: inline-flex;
  flex-direction: column;
  gap: 2px;
  padding: 8px 12px;
  background: var(--bg-1);
  border: 1px solid var(--line);
