  color: var(--ink-4);
  font-feature-settings: "tnum";
  letter-spacing: 0.02em;
  white-space: nowrap;
}
.csfloat-ticket-msg-count {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font: 500 11px/1 var(--ui);
  color: var(--ink-3);
}
.csfloat-ticket-msg-count.is-unread {
  color: var(--cta);
  font-weight: 600;
}
.csfloat-ticket-msg-count.is-unread::before {
  content: '';
  width: 6px;
  height: 6px;
  border-radius: 999px;
  background: var(--cta);
}
.csfloat-ticket-priority {
  font: 600 9px/1 var(--ui);
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: 2px 5px;
  border-radius: 3px;
}
.csfloat-ticket-priority.is-low {
  color: var(--ink-3);
  background: var(--bg-2);
}
.csfloat-ticket-priority.is-normal {
  color: var(--cta);
  background: rgba(59, 130, 246, 0.1);
}
.csfloat-ticket-priority.is-high {
  color: oklch(0.84 0.16 80);
  background: rgba(251, 191, 36, 0.1);
}
.csfloat-ticket-priority.is-urgent {
  color: oklch(0.78 0.18 30);
  background: rgba(248, 113, 113, 0.1);
}

/* CSFloat-1:1: video / loading placeholder block */
.csfloat-placeholder {
  background: linear-gradient(135deg, var(--bg-2) 0%, var(--bg-1) 60%);
  border: 1px solid var(--line);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 10px;
  padding: 24px;
  color: var(--ink-4);
  text-align: center;
  position: relative;
  overflow: hidden;
}
.csfloat-placeholder::before {
  content: '';
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(45deg, transparent 49%, var(--line) 49%, var(--line) 51%, transparent 51%),
    linear-gradient(-45deg, transparent 49%, var(--line) 49%, var(--line) 51%, transparent 51%);
  background-size: 24px 24px;
  opacity: 0.15;
  pointer-events: none;
}
.csfloat-placeholder-icon {
  width: 36px;
  height: 36px;
  border-radius: 999px;
  background: var(--bg-3);
  border: 1px solid var(--line);
  color: var(--ink-3);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  position: relative;
  z-index: 1;
}
.csfloat-placeholder-msg {
  font: 500 12px/1.4 var(--ui);
  color: var(--ink-3);
  letter-spacing: -0.005em;
  position: relative;
  z-index: 1;
  margin: 0;
}
.csfloat-placeholder-sub {
  font: 400 10px/1.4 var(--ui);
  color: var(--ink-4);
  letter-spacing: -0.005em;
  position: relative;
  z-index: 1;
  margin: 0;
}
.csfloat-placeholder.is-tall { min-height: 200px; }
.csfloat-placeholder.is-square { aspect-ratio: 1; }
.csfloat-placeholder.is-wide { aspect-ratio: 16/9; }
/* END support ticket + placeholder */

/* CSFloat-1:1: storefront filter strip — dense subnav for collections/sort */
.csfloat-store-strip {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 14px;
  background: var(--bg-1);
  border: 1px solid var(--line);
  border-radius: 10px;
  flex-wrap: wrap;
}
.csfloat-store-strip-group {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}
.csfloat-store-strip-divider {
  width: 1px;
  height: 18px;
  background: var(--line);
}
.csfloat-store-strip-link {
  height: 28px;
  padding: 0 10px;
  border-radius: 6px;
  font: 500 12px/1 var(--ui);
  color: var(--ink-3);
  letter-spacing: -0.005em;
  background: transparent;
  border: 0;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  text-decoration: none;
  transition: all 140ms cubic-bezier(0.2, 0.8, 0.2, 1);
}
.csfloat-store-strip-link:hover {
  background: var(--bg-2);
  color: var(--ink-1);
}
.csfloat-store-strip-link.is-active {
  background: var(--bg-2);
  color: var(--ink-1);
  box-shadow: inset 0 0 0 1px var(--line-2);
}
.csfloat-store-strip-link-count {
  font: 500 10px/1 var(--mono);
  color: var(--ink-4);
  font-feature-settings: "tnum";
  margin-left: 4px;
}
.csfloat-store-strip-link.is-active .csfloat-store-strip-link-count { color: var(--ink-3); }
.csfloat-store-strip-spacer { flex: 1 1 auto; }

/* CSFloat-1:1: search history list — recent searches dropdown */
.csfloat-history {
  display: flex;
  flex-direction: column;
  gap: 0;
}
.csfloat-history-row {
  display: grid;
  grid-template-columns: 14px 1fr auto;
  gap: 8px;
  align-items: center;
  padding: 8px 10px;
  border-radius: 5px;
  cursor: pointer;
  transition: background 100ms ease;
}
.csfloat-history-row:hover { background: var(--bg-2); }
.csfloat-history-row-icon {
  width: 14px;
  height: 14px;
  color: var(--ink-4);
  flex: 0 0 14px;
}
.csfloat-history-row-text {
  font: 400 13px/1 var(--ui);
  color: var(--ink-2);
  letter-spacing: -0.005em;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.csfloat-history-row-text > b {
  color: var(--ink-1);
  font-weight: 600;
}
.csfloat-history-row-remove {
  width: 16px;
  height: 16px;
  border-radius: 4px;
  border: 0;
  background: transparent;
  color: var(--ink-4);
  font: 500 11px/1 var(--ui);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
