.csfloat-spot-stat-meta {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-top: 4px;
  font: 400 12px/1.4 var(--ui);
  color: var(--ink-3);
  letter-spacing: -0.005em;
