}
/* END deal blob + hero meta strip */

/* CSFloat-1:1: tabbed market segment switcher — for primary/secondary market */
.csfloat-mkt-seg {
  display: inline-flex;
  background: var(--bg-2);
  border: 1px solid var(--line);
  border-radius: 10px;
