  font-size: 0.5em;
  color: var(--ink-3);
  font-weight: 500;
  margin-left: 4px;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}
.csfloat-stat-ribbon-item-meta {
  font: 400 11px/1 var(--ui);
  color: var(--ink-3);
  letter-spacing: -0.005em;
}
.csfloat-stat-ribbon-divider {
  width: 1px;
  align-self: stretch;
  background: var(--line);
  position: relative;
  z-index: 1;
}
@media (max-width: 720px) {
  .csfloat-stat-ribbon {
    padding: 20px 18px;
    gap: 16px;
  }
