  pointer-events: none;
}
.csfloat-grow-card:hover .csfloat-grow-card-glow { opacity: 1; }
.csfloat-grow-card-body {
  padding: 12px 14px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.csfloat-grow-card-name {
  font: 600 13px/1.3 var(--ui);
  color: var(--ink-1);
  letter-spacing: -0.005em;
  margin: 0;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.csfloat-grow-card-meta {
  display: inline-flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  font: 400 11px/1 var(--mono);
  color: var(--ink-3);
  font-feature-settings: "tnum";
}
.csfloat-grow-card-price {
  font: 700 14px/1 var(--mono);
  color: var(--ink-1);
  font-feature-settings: "tnum";
  letter-spacing: -0.005em;
}
.csfloat-grow-card-price::before {
  content: '$';
  font-size: 10px;
  color: var(--ink-3);
  margin-right: 1px;
  font-weight: 500;
  vertical-align: top;
}

/* CSFloat-1:1: avatar overlap row (small visual count of avatars) */
.csfloat-avatar-row {
  display: inline-flex;
  align-items: center;
  flex-direction: row-reverse;
  justify-content: flex-end;
}
.csfloat-avatar-row > .csfloat-avatar-row-img {
  width: 24px;
  height: 24px;
  border-radius: 999px;
  background: var(--bg-3);
  border: 2px solid var(--bg);
  margin-left: -8px;
