}
.csfloat-price-action-val.is-up { color: oklch(0.78 0.16 152); }
.csfloat-price-action-val.is-down { color: oklch(0.72 0.18 30); }
.csfloat-price-action-meta {
  font: 400 10px/1 var(--mono);
  color: var(--ink-4);
