}
.csfloat-badge-act > .csfloat-badge-act-btn.is-cta:hover { background: oklch(0.66 0.18 240); }

/* CSFloat-1:1: simple description line under headers */
.csfloat-desc-line {
  font: 400 13px/1.6 var(--ui);
  color: var(--ink-3);
  letter-spacing: -0.005em;
  margin: 0;
