  white-space: nowrap;
}
.csfloat-order-item-meta {
  display: inline-flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
  font: 400 11px/1.3 var(--ui);
  color: var(--ink-4);
}
.csfloat-order-item-meta-mono {
  font-family: var(--mono);
  font-feature-settings: "tnum";
  letter-spacing: 0.02em;
