  height: 30px !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  background-color: rgba(30, 32, 38, 0.55) !important;
  border: none !important;
  border-radius: 4px !important;
  color: rgba(255, 255, 255, 0.85) !important;
  pointer-events: none !important;
  z-index: 3 !important;
  backdrop-filter: blur(6px) !important;
  -webkit-backdrop-filter: blur(6px) !important;
  transition: background-color 0.15s ease !important;
}
.grid-card .grid-zoom svg {
  width: 16px !important;
  height: 16px !important;
}
.grid-card:hover .grid-zoom {
  background-color: rgba(40, 44, 52, 0.75) !important;
}
/* END CSFLOAT-1:1 PARITY ship #1391 */

/* CSFLOAT-1:1 PARITY ship #1392 — price chip $ prefix tinted GREEN like csfloat
   csfloat .price = 22px white bold w/ adjacent green app-price-icon badge. Mirror by
   tinting the leading "$" glyph green inside .grid-price. */
.grid-card .grid-price {
