}
.grid-card .float-bar > div,
.grid-card [class*="float-bar-segment"],
.grid-card [class*="float-bar-width"] {
  height: 8px !important;
}
.grid-card .wear-marker,
.grid-card [class*="wear-marker"] {
  width: 3px !important;
  height: 14px !important;
  background-color: rgb(217, 217, 217) !important;
  position: absolute !important;
  top: -3px !important;
  border-radius: 1px !important;
  z-index: 2 !important;
}
.grid-card .float-bar-fn { background-color: rgb(0, 128, 0) !important; }
.grid-card .float-bar-mw { background-color: rgb(24, 165, 24) !important; }
.grid-card .float-bar-ft { background-color: rgb(154, 205, 50) !important; }
.grid-card .float-bar-ww { background-color: rgb(205, 92, 92) !important; }
.grid-card .float-bar-bs { background-color: rgb(249, 36, 36) !important; }
/* END CSFLOAT-1:1 PARITY ship #1394 */

/* CSFLOAT-1:1 PARITY ship #1395 — top-right watch/cart icon stack on grid-card
   csfloat: top-right corner has a watch-toggle (heart) + add-to-cart icon stack.
   sboxmarket has .grid-star (heart) + .grid-cart-btn — make them match csfloat's
   icon-button chrome (28x28 circular buttons w/ subtle bg, top-right corner). */
.grid-card .grid-star,
.grid-card .grid-cart-btn {
