  font-weight: 700 !important;
  letter-spacing: -0.015em !important;
  text-shadow: none !important;
}
.cart-summary-actions {
  margin-top: 14px !important;
  gap: 10px !important;
}
.cart-summary-actions .btn {
  height: 40px !important;
  font-size: 13px !important;
  font-weight: 600 !important;
  letter-spacing: 0.005em !important;
}
/* END CSFLOAT-1:1 PARITY ship #1602 */

/* CSFLOAT-1:1 PARITY ship #1603 — cart drawer header + footer (modal-as-drawer)
   csfloat slide-out cart panel: header 56px tall, 16px horizontal pad, title
   left "Cart (N)" 15/700, close x right 32px; footer sticky bottom with 1px
   top divider, 16px pad, total label uppercase tracked, value 18px mono. */
.info-modal-panel:has(.cart-grid),
.info-modal-panel:has(.empty-inline .empty-icon) {
  max-width: 460px !important;
  width: 92vw !important;
  border-radius: 10px !important;
