  padding: 0 16px !important;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06) !important;
}
.info-modal-panel:has(.cart-grid) .info-modal-title,
.info-modal-panel:has(.empty-inline .empty-icon) .info-modal-title {
  font-size: 15px !important;
  font-weight: 700 !important;
  letter-spacing: -0.005em !important;
}
.info-modal-panel:has(.cart-grid) .info-modal-close,
.info-modal-panel:has(.empty-inline .empty-icon) .info-modal-close {
  width: 32px !important;
