/* ─────────────────────────────────────────────────────────────
   CSFLOAT-1:1 PARITY ship #2115 — Steam OAuth loading overlay
   Full-screen blur + centered spinner shown during the Steam
   OpenID redirect handoff so users get visual feedback.
   ───────────────────────────────────────────────────────────── */
.oauth-loading,
.steam-oauth-loading,
.signin-loading-overlay {
  position: fixed !important;
  inset: 0 !important;
  z-index: 9999 !important;
  background: rgba(15, 17, 21, 0.78) !important;
  backdrop-filter: blur(10px) saturate(1.1) !important;
  -webkit-backdrop-filter: blur(10px) saturate(1.1) !important;
  display: grid !important;
  place-items: center !important;
  animation: oauth-loading-in 200ms cubic-bezier(0.2, 0.8, 0.2, 1) !important;
}
@keyframes oauth-loading-in {
  from { opacity: 0; }
  to { opacity: 1; }
}
.oauth-loading-card,
.steam-oauth-loading > div,
.signin-loading-overlay > div,
.oauth-loading > div {
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  justify-content: center !important;
  gap: 16px !important;
  padding: 32px 40px !important;
  background: var(--bg-1) !important;
  border: 1px solid var(--line-2) !important;
  border-radius: 12px !important;
  box-shadow:
    rgba(0, 0, 0, 0.4) 0px 24px 48px -12px,
    rgba(0, 0, 0, 0.3) 0px 8px 24px -8px !important;
  min-width: 280px !important;
  text-align: center !important;
}
.oauth-loading-spinner {
  display: block !important;
  width: 40px !important;
  height: 40px !important;
  border-radius: 50% !important;
  border: 3px solid rgba(255, 255, 255, 0.10) !important;
  border-top-color: rgb(35, 123, 255) !important;
  animation: oauth-spin 800ms linear infinite !important;
}
@keyframes oauth-spin {
  to { transform: rotate(360deg); }
}
.oauth-loading-text,
.oauth-loading > div > p {
  font-family: Roboto, "Helvetica Neue", sans-serif !important;
  font-size: 14px !important;
  font-weight: 500 !important;
  color: rgb(255, 255, 255) !important;
  letter-spacing: normal !important;
