  height: 48px !important;
  border-radius: 8px !important;
  flex: 0 0 48px !important;
  background: #14161b !important;
  overflow: hidden !important;
  transition: box-shadow 140ms ease !important;
}
.db-table tbody td .db-item-cell > .db-thumb img {
  width: 100% !important;
  height: 100% !important;
  object-fit: contain !important;
}
.db-table tbody td .db-item-cell > div:not(.db-thumb) {
  min-width: 0 !important;
  display: flex !important;
  flex-direction: column !important;
  justify-content: center !important;
  gap: 2px !important;
}
.db-table tbody td .db-name,
.db-table tbody td a.db-name {
  display: block !important;
  font-size: 13px !important;
  font-weight: 500 !important;
  color: #e6e8ec !important;
  letter-spacing: -0.005em !important;
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
  text-decoration: none !important;
  max-width: 100% !important;
}
.db-table tbody td a.db-name:hover { color: #1ea5ff !important; text-decoration: none !important; }
.db-table tbody td .db-sub {
  font-family: Geist Mono, Roboto Mono, ui-monospace, monospace !important;
  font-size: 10px !important;
  font-weight: 500 !important;
  color: #6a7180 !important;
  letter-spacing: 0.02em !important;
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
}
/* END CSFLOAT-1:1 PARITY ship #2208 */

/* CSFLOAT-1:1 PARITY ship #2209 -- /db price cell with delta chip
   csfloat shows the floor price as a 13px tabular-num value plus an
   optional 11px delta chip (%) on the line below or inline. Green
   chip = above 24h average, red chip = below. Sboxmarket renders
   just the floor today, but we ship the chip styles now so when
   api.js starts returning priceDelta the chip lights up without
