}
.db-table tbody td.right.db-mono.accent .price-delta.flat {
  color: #6a7180 !important;
  background: rgba(106,113,128,0.10) !important;
  border: 1px solid rgba(106,113,128,0.20) !important;
}
.db-table tbody td.right.db-mono.accent .price-delta::before {
  content: "";
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: currentColor;
  display: inline-block;
}
.db-table tbody td.right.db-mono.accent .price-sub {
  display: block !important;
