  padding: 0 14px !important;
  font-size: 12px !important;
  font-weight: 500 !important;
  letter-spacing: 0 !important;
  text-transform: none !important;
  line-height: 32px !important;
  border-radius: 6px !important;
  background: rgba(255, 255, 255, 0.04) !important;
  border: 1px solid rgba(255, 255, 255, 0.1) !important;
  color: rgba(255, 255, 255, 0.85) !important;
  display: inline-flex !important;
  align-items: center !important;
  gap: 6px !important;
  text-decoration: none !important;
  transition: background-color 140ms ease, border-color 140ms ease, color 140ms ease !important;
}
.info-modal-body .btn.btn-ghost[style*="border: 1px solid var(--border)"]:hover,
.info-modal-body a.btn.btn-ghost[style*="border: 1px solid var(--border)"]:hover,
