  position: -webkit-sticky !important;
  position: sticky !important;
  top: 24px !important;
  align-self: flex-start !important;
  max-height: calc(100vh - 48px) !important;
  overflow: visible !important;
  z-index: 1 !important;
}
/* Ensure the parent grid does not clip the sticky child. overflow:hidden on
   any ancestor breaks position:sticky silently — explicit overflow:visible
   on the grid wrapper. */
body .modal.item-page .modal-grid,
body .modal.item-page .item-modal-grid,
body .modal.item-page > .modal-body {
  overflow: visible !important;
}
@media (max-width: 900px) {
