/* CSFLOAT-1:1 PARITY ship #5010 — click-to-zoom lightbox modal polish.
   csfloat: deep blur+darken backdrop, image centered with soft shadow, close
   button top-right of modal, 200ms fade-in + 240ms scale-in animation. */
@keyframes csfloat-zoom-fade-in {
  from { opacity: 0; }
  to   { opacity: 1; }
}
@keyframes csfloat-zoom-scale-in {
  from { opacity: 0; transform: scale(0.94); }
  to   { opacity: 1; transform: scale(1.00); }
}
.csfloat-zoom-modal-backdrop {
  position: fixed !important;
  inset: 0 !important;
  background: rgba(8, 10, 16, 0.88) !important;
  backdrop-filter: blur(10px) saturate(140%) !important;
  -webkit-backdrop-filter: blur(10px) saturate(140%) !important;
  z-index: 9800 !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  padding: 32px !important;
  animation: csfloat-zoom-fade-in 200ms ease !important;
}
.csfloat-zoom-modal {
  position: relative !important;
  max-width: 90vw !important;
  max-height: 90vh !important;
  display: flex !important;
